SELECT COUNT(*) FROM PAYMENT_MEMBER WHERE delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND TO_DATE(join_start_date,'yyyy-MM-dd') BETWEEN #{join_start_date} AND #{join_end_date}

${pagingTop} SELECT homepage_id, pay_member_idx, pay_family_member_idx, pay_member_name, phone, tel, loan_number, birth, TO_CHAR(join_start_date,'yyyy-MM-dd') AS join_start_date, TO_CHAR(join_end_date,'yyyy-MM-dd') AS join_end_date, use_type, sex, REGEXP_REPLACE(REVERSE(REGEXP_REPLACE(REVERSE(TO_CHAR(sponsorship_amount)), '(\d{3})','\1,')), '^,','') AS sponsorship_amount, approve_yn, add_id, add_date, add_ip, modify_id, modify_date, delete_id, delete_date, delete_ip, delete_yn, etc, email_address, family_yn, family_count FROM PAYMENT_MEMBER WHERE delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND TO_DATE(join_start_date,'yyyy-MM-dd') BETWEEN #{join_start_date} AND #{join_end_date}
ORDER BY pay_member_idx DESC ${pagingBottom}

mapper.update:
UPDATE
	PAYMENT_MEMBER
SET
	family_yn = #{family_yn}
WHERE
	pay_member_idx = #{pay_member_idx}

DELETE FROM
    PAYMENT_FAMILY_MEMBER
WHERE
    HOMEPAGE_ID = #{homepage_id}
AND pay_family_member_idx = #{pay_member_idx}

UPDATE
	PAYMENT_MEMBER
SET
	approve_yn = #{approve_yn}
WHERE
	pay_member_idx = #{pay_member_idx}
